def find_pairs(arr, target, decimals):
    pairs = []
    i = 0
    n = len(arr)
    while (i < n):
        j = (i + 1)
        while (j < n):
            if (round((arr[i] + arr[j]), decimals) == round(target, decimals)):
                pairs.append((arr[i], arr[j]))
            j = (j + 1)
        i = (i + 1)
    return pairs

